import {clamp} from './math.mjs';
export const ASSETS = new URL('../../assets/',import.meta.url);
export const asset = name => new URL(name,ASSETS).href;
export async function image(url) {
  const img=new Image();img.decoding='async';
  await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('图片无法读取'));img.src=url;});
  return img;
}
export function offscreen(w,h) { const c=document.createElement('canvas');c.width=w;c.height=h;return c; }
export function sampleImage(img,w,h) {
  const c=offscreen(w,h),ctx=c.getContext('2d',{willReadFrequently:true});
  const s=Math.max(w/img.width,h/img.height),dw=img.width*s,dh=img.height*s;
  ctx.drawImage(img,(w-dw)/2,(h-dh)/2,dw,dh);return ctx.getImageData(0,0,w,h);
}
export function bilinear(data,w,h,x,y,ch=0,stride=4) {
  x=clamp(x,0,w-1);y=clamp(y,0,h-1);
  const a=Math.floor(x),b=Math.floor(y),u=x-a,v=y-b;
  const i=(b*w+a)*stride+ch,j=(b*w+Math.min(w-1,a+1))*stride+ch;
  const k=(Math.min(h-1,b+1)*w+a)*stride+ch,l=(Math.min(h-1,b+1)*w+Math.min(w-1,a+1))*stride+ch;
  return (data[i]*(1-u)+data[j]*u)*(1-v)+(data[k]*(1-u)+data[l]*u)*v;
}
export function range(parent,label,min,max,value,step,onChange) {
  const wrap=document.createElement('label'), text=document.createElement('span'), out=document.createElement('output'), input=document.createElement('input');
  text.textContent=label;input.type='range';Object.assign(input,{min,max,step,value});
  input.setAttribute('aria-label',label);out.value=String(value);
  input.addEventListener('input',()=>{out.value=input.value;onChange(Number(input.value));});
  wrap.append(text,input,out);parent.append(wrap);return input;
}
export function select(parent,label,items,onChange) {
  const wrap=document.createElement('label'),span=document.createElement('span'),input=document.createElement('select');span.textContent=label;
  input.setAttribute('aria-label',label);items.forEach(([v,t])=>input.add(new Option(t,v)));
  input.addEventListener('change',()=>onChange(input.value));wrap.append(span,input);parent.append(wrap);return input;
}
export function button(parent,label,onClick) { const b=document.createElement('button');b.type='button';b.textContent=label;b.addEventListener('click',onClick);parent.append(b);return b; }
export function fileInput(parent,label,accept,limitMB,onFile) {
  const wrap=document.createElement('label');wrap.className='file-button';wrap.textContent=label;
  const f=document.createElement('input');f.type='file';f.accept=accept;
  f.addEventListener('change',async()=>{const file=f.files?.[0];if(!file)return;try{if(file.size>limitMB*1024*1024)throw new Error(`文件不能超过 ${limitMB} MB`);await onFile(file);}catch(e){document.querySelector('#status').textContent=e.message;}finally{f.value='';}});
  wrap.append(f);parent.append(wrap);return f;
}
export class Stage {
  constructor(canvas,status) {
    this.canvas=canvas;this.ctx=canvas.getContext('2d');this.statusElement=status;
    this.pointer={x:.5,y:.5,down:false,dx:0,dy:0};this.keys=new Set();this.playing=!matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.width=0;this.height=0;this.t=0;this.frame=0;this.dirty=true;this.rafHz=0;this.last=0;
    this.abort=new AbortController();const options={signal:this.abort.signal};
    this.resize=()=>{const r=canvas.getBoundingClientRect();this.width=Math.max(1,Math.round(r.width));this.height=Math.max(1,Math.round(r.height));this.dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(this.width*this.dpr);canvas.height=Math.round(this.height*this.dpr);this.ctx.setTransform(this.dpr,0,0,this.dpr,0,0);this.dirty=true;this.effect?.resize?.();};
    this.observer=new ResizeObserver(this.resize);this.observer.observe(canvas);
    const move=e=>{const r=canvas.getBoundingClientRect(),x=clamp((e.clientX-r.left)/r.width),y=clamp((e.clientY-r.top)/r.height);this.pointer.dx=x-this.pointer.x;this.pointer.dy=y-this.pointer.y;this.pointer.x=x;this.pointer.y=y;this.effect?.pointer?.(this.pointer,e);this.dirty=true;};
    canvas.addEventListener('pointerdown',e=>{this.pointer.down=true;canvas.setPointerCapture(e.pointerId);move(e);canvas.focus({preventScroll:true});},options);
    canvas.addEventListener('pointermove',move,options);
    const release=()=>{this.pointer.down=false;this.pointer.dx=0;this.pointer.dy=0;this.effect?.release?.();};
    canvas.addEventListener('pointerup',release,options);canvas.addEventListener('pointercancel',release,options);canvas.addEventListener('lostpointercapture',release,options);
    window.addEventListener('blur',()=>{this.keys.clear();release();},options);
    canvas.addEventListener('keydown',e=>{if(e.key.startsWith('Arrow')){e.preventDefault();this.keys.add(e.key);this.effect?.key?.(e.key);this.dirty=true;}if(e.code==='Space'){e.preventDefault();document.querySelector('#play').click();}if(e.key.toLowerCase()==='r')document.querySelector('#reset').click();},options);
    window.addEventListener('keyup',e=>this.keys.delete(e.key),options);
    document.addEventListener('visibilitychange',()=>{this.last=0;this.effect?.visibility?.(!document.hidden&&this.playing);},options);
    this.resize();
  }
  status(text){this.statusElement.textContent=text;}
  setPlaying(on){this.playing=on;this.last=0;this.effect?.visibility?.(on&&!document.hidden);this.dirty=true;this.onPlayingChange?.();}
  start(effect) {
    this.effect=effect;this.resize();this.effect.visibility?.(this.playing&&!document.hidden);
    const loop=now=>{this.raf=requestAnimationFrame(loop);if(document.hidden){this.last=0;return;}
      const elapsed=this.last?Math.min((now-this.last)/1000,.05):0;this.last=now;
      if(elapsed)this.rafHz=this.rafHz*.94+(1/elapsed)*.06;
      const dt=this.playing?elapsed:0;if(this.playing)this.t+=dt;
      if((this.playing&&!effect.static)||this.dirty){try{effect.render(dt);this.frame++;this.onRendered?.();for(const el of document.querySelectorAll('.controls input[type="range"]')){const out=el.parentElement.querySelector('output');if(out)out.value=el.value;}}catch(e){this.status('运行失败：'+e.message);console.error(e);this.setPlaying(false);}this.dirty=false;}
    };this.raf=requestAnimationFrame(loop);
  }
  dispose(){cancelAnimationFrame(this.raf);this.abort.abort();this.observer.disconnect();this.effect?.dispose?.();}
}
export function sky(ctx,w,h,top='#0c2733',bottom='#091319') {const g=ctx.createLinearGradient(0,0,w*.25,h);g.addColorStop(0,top);g.addColorStop(1,bottom);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);}
export function caption(ctx,text,x,y,color='#b6cfcc',size=11) {ctx.fillStyle=color;ctx.font=`${size}px ui-monospace,Consolas,monospace`;ctx.fillText(text,x,y);}

export function coverFit(sw,sh,w,h){const scale=Math.max(w/sw,h/sh);return {scale,x:(w-sw*scale)/2,y:(h-sh*scale)/2,width:sw*scale,height:sh*scale};}
export function sourcePointer(p,sw,sh,w,h){const f=coverFit(sw,sh,w,h);return {x:clamp((p.x*w-f.x)/f.width),y:clamp((p.y*h-f.y)/f.height)};}
import {camera,box,renderFaces,imageQuad,clamp} from './math.mjs';
import {asset,image,range,button,offscreen,coverFit} from './core.mjs';

// Catalog chapters are embedded by the builder, so art and copy share one source.
export async function create(stage,controls) {
  const chapters=JSON.parse(document.querySelector('#portal-chapters').textContent);
  const [art,patina]=await Promise.all([
    Promise.all(chapters.map(chapter=>image(asset(chapter.image)))),
    image(asset('studies/portal-patina.png')),
  ]);
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const theater=document.querySelector('.theater'),hero=document.querySelector('.hero-copy');
  const eyebrow=hero.querySelector('.eyebrow'),heading=hero.querySelector('h1'),body=hero.querySelector('p');
  const stageTag=document.querySelector('.stage-tag'),coordinate=document.querySelector('.study-coordinate');
  const telemetry=document.querySelector('.telemetry');
  const before=offscreen(1,1),beforeContext=before.getContext('2d');
  let chapterIndex=0,progress=0,target=0,yaw=0,auto=false,custom=false;
  let transition=1,chapterTime=0,travelTime=0;
  const transitionSeconds=1.2,holdSeconds=12;

  const edition=document.createElement('div');edition.className='portal-edition';
  edition.innerHTML='<span>彼处 <b>ELSEWHERE</b></span><small>空间声音手记 / CONCEPT JOURNAL</small>';
  theater.append(edition);
  const folio=document.createElement('aside');folio.className='portal-folio';
  folio.setAttribute('aria-label','本章产品札记');
  folio.innerHTML='<div class="portal-folio-top"><span></span><b></b></div><h2></h2><p></p><div class="portal-tags"></div>';
  theater.append(folio);
  const note=document.createElement('div');note.className='portal-note';
  note.innerHTML='<span>FROM THE FIELD</span><p></p><small></small>';
  theater.append(note);
  const chapterMark=document.createElement('div');chapterMark.className='portal-chapter-mark';
  chapterMark.setAttribute('aria-hidden','true');theater.append(chapterMark);
  hero.setAttribute('aria-live','polite');hero.setAttribute('aria-atomic','true');

  const slider=range(controls,'穿越进度',0,100,0,1,v=>{target=v/100;custom=true;auto=false;stage.dirty=true;});
  button(controls,'穿过画框',()=>select(1));
  button(controls,'回头看',()=>select(2));
  const roamButton=button(controls,'自动漫游',()=>{if(auto){auto=false;stage.dirty=true;}else select(3);});

  // Patinated jambs and threshold slabs surround the photographic environment.
  // The camera traverses z=0; the environment acts as a distant backdrop.
  const faces=[];
  for(const z of [0,-3]) {
    for(const [center,size] of [
      [[-4.65,2.2,z],[.18,7,.25]],[[4.65,2.2,z],[.18,7,.25]],
      [[0,5.65,z],[9.5,.15,.25]],[[0,-1.2,z],[9.5,.1,.4]],
    ])for(const side of box(center,size,'#756348'))faces.push(...imageQuad(side.points,patina,1,3));
  }

  function writeCopy() {
    const chapter=chapters[chapterIndex],number=String(chapterIndex+1).padStart(2,'0');
    document.body.style.setProperty('--accent',chapter.accent);
    document.body.dataset.chapter=chapter.id;
    hero.dataset.chapter=folio.dataset.chapter=chapter.id;
    eyebrow.replaceChildren();
    const name=document.createElement('span');name.textContent=chapter.english;
    const rule=document.createElement('i'),index=document.createElement('span');index.textContent=number+' / 04';
    eyebrow.append(name,rule,index);
    [...heading.children].forEach((line,i)=>line.textContent=chapter.headline[i]);
    body.textContent=chapter.body;
    document.querySelector('#interact > span').textContent=chapter.action;
    stageTag.replaceChildren();
    const dash=document.createElement('span'),tag=document.createElement('b');tag.textContent=chapter.kicker;
    stageTag.append(dash,document.createTextNode('ELSEWHERE / FIELD JOURNAL'),tag);
    coordinate.querySelector('span').textContent=chapter.coordinate;
    coordinate.querySelector('b').textContent=chapter.time;
    folio.querySelector('.portal-folio-top span').textContent='PRODUCT NOTE / '+number;
    folio.querySelector('.portal-folio-top b').textContent=chapter.location;
    folio.querySelector('h2').textContent=chapter.feature;
    folio.querySelector('p').textContent=chapter.detail;
    const tags=folio.querySelector('.portal-tags');tags.replaceChildren();
    for(const text of chapter.tags){const tag=document.createElement('span');tag.textContent=text;tags.append(tag);}
    note.querySelector('p').textContent=chapter.note;
    note.querySelector('small').textContent=chapter.location+' / '+chapter.time;
    chapterMark.textContent=number;
    telemetry.querySelector('.telemetry-bottom span').textContent=chapter.english;
    telemetry.setAttribute('aria-label','当前手记');
    roamButton.setAttribute('aria-pressed',String(auto));
  }

  function select(index,{continueRoam=false,animate=true}={}) {
    if(animate&&stage.playing&&!reduced.matches&&stage.frame>0){
      before.width=stage.canvas.width;before.height=stage.canvas.height;
      beforeContext.drawImage(stage.canvas,0,0);transition=0;
    }else transition=1;
    chapterIndex=index;custom=false;chapterTime=0;travelTime=0;
    const pose=chapters[index].pose;target=pose.progress;yaw=pose.yaw;
    auto=continueRoam||index===3;
    // A paused chapter selection stays paused, including the roaming chapter.
    if(!animate||!stage.playing||reduced.matches)progress=target;
    writeCopy();stage.dirty=true;
  }
  function reset(){select(0,{animate:false});progress=0;slider.value=0;}
  const scenes={label:'THE FIELD ATLAS',kind:'JOURNAL',items:chapters.map((chapter,index)=>({
    ...chapter,apply:()=>select(index),active:()=>!custom&&chapterIndex===index,
  }))};
  function drawEnvironment(ctx,w,h) {
    const artwork=art[chapterIndex],p=stage.pointer;
    const drift=reduced.matches?0:Math.sin(stage.t*.11)*.009;
    const zoom=1.035+progress*.06+Math.sin(yaw)*.025;
    const fit=coverFit(artwork.width,artwork.height,w*zoom,h*zoom);
    const ox=(p.x-.5)*-13+drift*w,oy=(p.y-.5)*-9;
    ctx.drawImage(artwork,fit.x-(w*zoom-w)*.5+ox,fit.y-(h*zoom-h)*.5+oy,fit.width,fit.height);
    ctx.save();ctx.globalAlpha=.3;
    // Keep the foreground architecture at the periphery of the content aperture.
    ctx.beginPath();ctx.rect(0,0,w*.09,h);ctx.rect(w*.91,0,w*.09,h);ctx.rect(0,0,w,h*.035);ctx.rect(0,h*.965,w,h*.035);ctx.clip();
    const eye=[(p.x-.5)*.55,1.68+(p.y-.5)*-.2,5.7-progress*10.1];
    const cam=camera(eye,[eye[0]+Math.sin(yaw),eye[1],eye[2]-Math.cos(yaw)],w,h,.86);
    if(w>600)renderFaces(ctx,faces,cam);ctx.restore();
    const shade=ctx.createLinearGradient(0,0,w,0);
    shade.addColorStop(0,'#061113ee');shade.addColorStop(.2,'#071418ba');shade.addColorStop(.49,'#07141815');shade.addColorStop(1,'#06101805');
    ctx.fillStyle=shade;ctx.fillRect(0,0,w,h);
    const bottom=ctx.createLinearGradient(0,h*.45,0,h);
    bottom.addColorStop(0,'#06111300');bottom.addColorStop(1,'#061113b3');
    ctx.fillStyle=bottom;ctx.fillRect(0,0,w,h);
  }
  writeCopy();
  return {
    scenes,reset,interact:()=>select((chapterIndex+1)%chapters.length),
    key(key){custom=true;auto=false;if(key==='ArrowUp')target=clamp(target+.08);if(key==='ArrowDown')target=clamp(target-.08);if(key==='ArrowLeft')yaw-=.12;if(key==='ArrowRight')yaw+=.12;},
    render(dt){
      if(auto&&dt){
        chapterTime+=dt;travelTime+=dt;
        if(chapterTime>=holdSeconds)select((chapterIndex+1)%chapters.length,{continueRoam:true});
        target=clamp(chapters[chapterIndex].pose.progress+Math.sin(travelTime*.28)*.16);
      }
      progress=dt?progress+(target-progress)*(1-Math.exp(-dt*3)):target;
      slider.value=String(Math.round(progress*100));
      const {ctx,width:w,height:h}=stage;
      ctx.clearRect(0,0,w,h);drawEnvironment(ctx,w,h);
      transition=(!stage.playing||reduced.matches)?1:Math.min(1,transition+dt/transitionSeconds);
      const blend=transition*transition*(3-2*transition);
      if(transition<1){
        ctx.save();ctx.globalAlpha=1-blend;
        const scale=1+blend*.075;ctx.translate(w/2,h/2);ctx.scale(scale,scale);
        ctx.drawImage(before,-w/2,-h/2,w,h);ctx.restore();
        ctx.save();ctx.globalAlpha=Math.sin(transition*Math.PI)*.25;
        ctx.strokeStyle=chapters[chapterIndex].accent;ctx.lineWidth=1;
        const aperture=.22+blend*.82;ctx.strokeRect(w*(1-aperture)*.5,h*(1-aperture)*.5,w*aperture,h*aperture);ctx.restore();
      }
      theater.style.setProperty('--chapter-enter',String(blend));
      roamButton.setAttribute('aria-pressed',String(auto));
      const chapter=chapters[chapterIndex];
      stage.status(chapter.location+' · '+chapter.time+(auto?' · 漫游中':' · 手记已展开'));
    },
    inspect:()=>({progress,target,auto,z:5.7-progress*10.1,faces:faces.length,yaw,
      chapter:chapters[chapterIndex].id,chapterIndex,chapterTime,transition,
      art:chapters[chapterIndex].image,text:chapters[chapterIndex].headline.join(''),
      texturesLoaded:art.length+1,transitionSeconds,holdSeconds}),
  };
#!/usr/bin/env python3
"""Build studies 03–08 and the shared gallery; leave both legacy engines untouched."""
from __future__ import annotations
import argparse
import html
import json
import runpy
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def outputs() -> dict[Path, str]:
    catalog = json.loads((ROOT / 'src/studies/catalog.json').read_text(encoding='utf-8'))
    template = (ROOT / 'src/studies/page.html').read_text(encoding='utf-8')
    generated = {}
    for item in catalog:
        output = ROOT / f'dist/{item["slug"]}.html'
        shell = runpy.run_path(str(ROOT / 'src/hall/build.py'))['render'](item['id'], output)
        page = template
        extra = ''
        if item['id'] in ('portal', 'temporal', 'fluid'):
            chapters = json.dumps(item['chapters'], ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
            extra = (f'\n<link rel="stylesheet" href="../src/studies/{item["id"]}.css">'
                     f'\n<script type="application/json" id="{item["id"]}-chapters">' + chapters + '</script>')
        page = page.replace('@@STUDYEXTRA@@', extra)
        for key, value in item.items():
            page = page.replace('@@' + key.upper() + '@@', html.escape(str(value), quote=True))
        for key, value in shell.items():
            if key in ('style', 'script'):
                tag = 'style' if key == 'style' else 'script'
                value = f'<{tag}>\n{value}\n</{tag}>'
            page = page.replace('<!-- HALL:' + key.upper() + ' -->', value)
        if '@@' in page:
            raise ValueError(f'Unresolved template token in {item["slug"]}')
        generated[ROOT / f'dist/{item["slug"]}.html'] = page
    generated[ROOT / 'index.html'] = (ROOT / 'src/showcase.html').read_text(encoding='utf-8')
    return generated

def build(check: bool = False) -> None:
    stale = []
    for path, text in outputs().items():
        if check:
            if not path.is_file() or path.read_text(encoding='utf-8') != text:
                stale.append(str(path.relative_to(ROOT)))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding='utf-8')
            print('Built', path.relative_to(ROOT))
    if stale:
        raise SystemExit('Out-of-date generated files: ' + ', '.join(stale))
    if check:
        print('Studies and gallery are reproducible.')

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    build(parser.parse_args().check)
#!/usr/bin/env python3
"""Check the new static resource graph without requiring legacy media locally."""
from pathlib import Path
from html.parser import HTMLParser
import json
import re
import subprocess
import sys
import xml.etree.ElementTree as ET
from build_studies import ROOT, build

class Links(HTMLParser):
    def __init__(self):super().__init__();self.paths=[]
    def handle_starttag(self,tag,attrs):
        a=dict(attrs)
        if tag in ('script','img') and a.get('src'):self.paths.append(a['src'])
        if tag=='link' and a.get('href'):self.paths.append(a['href'])

build(check=True)
for path in (ROOT/'src/studies').glob('*.mjs'):
    subprocess.run(['node','--check',str(path)],check=True)
    for rel in re.findall(r"(?:from\s*|import\()\s*['\"](\./[^'\"]+)['\"]",path.read_text(encoding='utf-8')):
        assert (path.parent/rel).is_file(),(path,rel)
for path in (ROOT/'assets/studies').glob('*.svg'):ET.parse(path)
for item in json.loads((ROOT/'src/studies/catalog.json').read_text(encoding='utf-8')):
    path=ROOT/f'dist/{item["slug"]}.html';p=Links();p.feed(path.read_text(encoding='utf-8'))
    for rel in p.paths:assert (path.parent/rel).resolve().is_file(),(path,rel)
    assert (ROOT/'assets/studies'/item['cover']).is_file()
    if item['id'] == 'temporal':
        chapters = item['chapters']
        assert 4 <= len(chapters) <= 5
        for field in ('id', 'image', 'body', 'note', 'kicker'):
            assert len({chapter[field] for chapter in chapters}) == len(chapters), field
        for chapter in chapters:
            assert (ROOT/'assets'/chapter['image']).is_file()
            assert all(chapter[key] for key in ('headline', 'detail', 'feature', 'annotation', 'action'))
    if item['id'] == 'fluid':
        chapters = item['chapters']
        assert 4 <= len(chapters) <= 5
        for field in ('id', 'image', 'body', 'note', 'kicker', 'material'):
            assert len({chapter[field] for chapter in chapters}) == len(chapters), field
        for chapter in chapters:
            assert (ROOT/'assets'/chapter['image']).is_file()
            assert all(chapter[key] for key in ('headline', 'detail', 'feature', 'annotation', 'action', 'flow'))
            assert len(chapter['swatches']) == len(chapter['swatchNames']) == 3
s=(ROOT/'src/showcase.html').read_text(encoding='utf-8')
assert s.count('class="card')==8
assert 'href="dist/index.html"' in s and 'href="dist/matrix-battle.html"' in s
assert not any('placeholder' in p.name.lower() for p in (ROOT/'assets/studies').iterdir())
print('Native module/resource graph, SVGs, eight-entry gallery and generated files: PASS')

import {Stage} from './core.mjs';
import {filmstrip} from './filmstrip.mjs';
const canvas=document.querySelector('#canvas'),status=document.querySelector('#status'),loading=document.querySelector('#loading');
const play=document.querySelector('#play'),reset=document.querySelector('#reset'),snapshot=document.querySelector('#snapshot');
const id=document.body.dataset.study;
const modules={portal:()=>import('./portal.mjs'),temporal:()=>import('./temporal.mjs'),fluid:()=>import('./fluid.mjs'),optical:()=>import('./optical.mjs'),shadow:()=>import('./shadow.mjs'),folding:()=>import('./folding.mjs')};
let stage,effect;
function sync(){document.querySelector('#play-label').textContent=stage.playing?'暂停巡航':'继续巡航';document.querySelector('.play-glyph').textContent=stage.playing?'Ⅱ':'▷';document.querySelector('#play-state').textContent=stage.playing?'影像运行中':'影像已暂停';play.setAttribute('aria-pressed',String(stage.playing));play.setAttribute('aria-label',stage.playing?'暂停巡航':'继续巡航');}
try {
  if(!modules[id])throw new Error('未知实验');
  stage=new Stage(canvas,status);stage.onPlayingChange=sync;sync();
  play.addEventListener('click',()=>{stage.setPlaying(!stage.playing);sync();});
  reset.addEventListener('click',()=>{effect?.reset?.();stage.t=0;stage.dirty=true;});
  snapshot.addEventListener('click',()=>{try{canvas.toBlob(blob=>{if(!blob){stage.status('保存失败：没有可导出的画面');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${id}-${Date.now()}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);},'image/png');}catch(e){stage.status('保存失败：'+e.message);}});
  effect=await (await modules[id]()).create(stage,document.querySelector('#controls'));stage.start(effect);filmstrip(stage,effect.scenes);loading.hidden=true;
  const clean=document.querySelector('#clean'),about=document.querySelector('#about');
  clean.addEventListener('click',()=>{const on=document.body.classList.toggle('study-clean');clean.setAttribute('aria-pressed',String(on));});
  document.querySelector('#interact').addEventListener('click',()=>{if(effect.interact){effect.interact();return;}document.body.classList.add('study-clean');clean.setAttribute('aria-pressed','true');canvas.focus({preventScroll:true});});
  let resume=false;
  document.querySelector('#about-open').addEventListener('click',()=>{resume=stage.playing;stage.setPlaying(false);about.showModal();});
  document.querySelector('#about-close').addEventListener('click',()=>about.close());
  about.addEventListener('close',()=>stage.setPlaying(resume));
  window.addEventListener('keydown',e=>{if(e.defaultPrevented||about.open||e.target.closest('input,select,textarea,button,a,summary'))return;if(e.code==='Space'){e.preventDefault();play.click();}if(e.key.toLowerCase()==='h')clean.click();});
  // Stable inspection hooks for tests; no executable input or remote controls.
  window.VisualStudy={id,pause:()=>{stage.setPlaying(false);sync();},play:()=>{stage.setPlaying(true);sync();},reset:()=>reset.click(),inspect:()=>({id,playing:stage.playing,frame:stage.frame,width:stage.width,height:stage.height,rafHz:Math.round(stage.rafHz),...effect.inspect?.()})};
  window.addEventListener('pagehide',()=>stage.dispose(),{once:true});
} catch(e) {
  stage?.dispose();loading.textContent='画面未能启动：'+e.message+'。请从仓库根目录启动静态服务器。';status.textContent='未启动';play.disabled=reset.disabled=snapshot.disabled=true;console.error(e);
}
import {asset} from './core.mjs';

// Each effect owns its presets and predicates; this shell only presents them.
export function filmstrip(stage, scenes) {
  const footer=document.querySelector('.study-footer'),strip=footer.querySelector('.study-strip');
  const id=document.body.dataset.study,items=scenes.items;
  document.querySelector('#study-atlas-label').textContent=scenes.label;
  document.querySelector('#study-total').textContent='/ '+String(items.length).padStart(2,'0');
  strip.style.setProperty('--scene-count',items.length);
  let current=-2;
  const reveal=button=>{const a=button.getBoundingClientRect(),b=strip.getBoundingClientRect();strip.scrollLeft+=a.left-b.left-(strip.clientWidth-a.width)/2;};
  const buttons=items.map((item,index)=>{
    const button=document.createElement('button');button.type='button';button.className='hall-card study-card';button.dataset.scene=item.id;
    const thumb=document.createElement('span');thumb.className='hall-thumb';
    const img=document.createElement('img');img.src=asset(item.image || `studies/filmstrip/${id}-${item.id}.webp`);img.alt='';img.width=160;img.height=96;thumb.append(img);
    const copy=document.createElement('span');copy.className='hall-card-copy';
    const number=document.createElement('small');number.textContent=String(index+1).padStart(2,'0')+' / '+scenes.kind;
    const title=document.createElement('strong');title.textContent=item.title;copy.append(number,title);button.append(thumb,copy);
    button.addEventListener('click',()=>{item.apply();stage.dirty=true;sync();reveal(button);});
    // Editorial strips keep a pointer target still until its click is delivered.
    button.addEventListener('focus',()=>{if(!['portal','temporal','fluid'].includes(id)||button.matches(':focus-visible'))reveal(button);});strip.append(button);return button;
  });
  function sync(){
    const index=items.findIndex(item=>item.active());
    if(index===current)return;
    current=index;
    buttons.forEach((button,i)=>{button.setAttribute('aria-pressed',String(i===index));if(i===index)button.setAttribute('aria-current','true');else button.removeAttribute('aria-current');});
    document.querySelector('#study-current').textContent=index<0?'—':String(index+1).padStart(2,'0');
    footer.style.setProperty('--hall-position',Math.max(0,index)/(items.length-1));
    footer.classList.toggle('study-custom',index<0);
    if(index>=0)reveal(buttons[index]);
  }
  document.querySelector('#study-prev').addEventListener('click',()=>buttons[(Math.max(0,current)-1+items.length)%items.length].click());
  document.querySelector('#study-next').addEventListener('click',()=>buttons[(current+1)%items.length].click());
  stage.onRendered=sync;sync();
}
#!/usr/bin/env python3
"""Playwright interaction checks for studies 03-08 (offline or HTTP mode)."""
from __future__ import annotations
import argparse
import hashlib
import json
import threading
import tempfile
import functools
import sys
from pathlib import Path
from http.server import ThreadingHTTPServer
from playwright.sync_api import sync_playwright
from studies_inline import ROOT, bundle, inline_page
sys.path.insert(0, str(ROOT / 'scripts'))
from serve import RangeRequestHandler


def run(args):
    catalog=json.loads((ROOT/'src/studies/catalog.json').read_text(encoding='utf-8'))
    result={'loading':'offline-inline' if args.inline else 'HTTP native modules','checks':[],'screenshots':[]}
    args.output.mkdir(parents=True,exist_ok=True)
    server=None
    if not args.inline:
        server=ThreadingHTTPServer(('127.0.0.1',0),functools.partial(RangeRequestHandler,directory=str(ROOT)))
        threading.Thread(target=server.serve_forever,daemon=True).start()
    code=bundle(args.video_fixture) if args.inline else None
    def check(name,value):
        assert value, name
        result['checks'].append(name)
        print('PASS',name,flush=True)
    with sync_playwright() as p:
        kw={'headless':True,'args':['--no-sandbox','--disable-dev-shm-usage']}
        if args.chromium:kw['executable_path']=args.chromium
        browser=p.chromium.launch(**kw)
        for item in catalog:
            errors=[]
            page=browser.new_page(viewport={'width':1440,'height':900},device_scale_factor=1,accept_downloads=True)
            page.on('pageerror',lambda e:errors.append(str(e)))
            def load():
                if args.inline:
                    page.goto('about:blank');page.set_content(inline_page(item['slug']));page.add_script_tag(content=code)
                else:page.goto(f'http://127.0.0.1:{server.server_port}/dist/{item["slug"]}.html')
                page.wait_for_function('window.VisualStudy !== undefined',timeout=12000)
            def inspect():return page.evaluate('VisualStudy.inspect()')
            def pause():page.evaluate('VisualStudy.pause()');page.wait_for_timeout(80)
            def change(label,value):
                el=page.get_by_label(label,exact=True)
                el.fill(str(value));el.dispatch_event('input');page.wait_for_timeout(80)
            def digest():return hashlib.sha256(page.locator('#canvas').screenshot()).hexdigest()
            load();page.wait_for_timeout(350);check(item['id']+' initialized',inspect()['frame']>0)
            check(item['id']+' default local filmstrip',page.locator('.hall-scene-footer').is_visible() and page.locator('.hall-atlas').is_hidden())
            check(item['id']+' local strip has only content buttons',4<=page.locator('.study-strip > button').count()<=5 and page.locator('.hall-scene-footer a').count()==0)
            check(item['id']+' local thumbnails decoded',page.locator('.study-strip img').evaluate_all('(imgs)=>imgs.every(i=>i.complete&&i.naturalWidth>0)'))
            check(item['id']+' initial content accented',page.locator('.study-strip [aria-current]').count()==1)
            page.locator('.hall-open-atlas').click()
            check(item['id']+' atlas only opens on request',page.locator('body.hall-experiences').count()==1 and page.locator('.hall-atlas').is_visible() and page.locator('.hall-scene-footer').is_hidden() and page.locator('.hall-strip a').count()==8)
            page.locator('#about-open').click();page.keyboard.press('Escape')
            page.wait_for_function('!document.querySelector("#about").open')
            check(item['id']+' notes Escape preserves underlying atlas',page.locator('.hall-atlas').is_visible() and page.locator('.hall-open-atlas').get_attribute('aria-expanded')=='true')
            page.keyboard.press('Escape')
            check(item['id']+' escape restores local content and focus',page.locator('.hall-atlas').is_hidden() and page.locator('.hall-open-atlas').evaluate('(e)=>e===document.activeElement'))
            page.screenshot(path=str(args.output/(item['id']+'-entry.png')),full_page=True)
            result['screenshots'].append(item['id']+'-entry.png')
            page.locator('body').click(position={'x':2,'y':2});before=inspect()['playing'];page.keyboard.press('Space')
            check(item['id']+' global SPACE toggles once',inspect()['playing'] is not before)
            page.locator('#clean').click();check(item['id']+' clean canvas hides HUD',page.locator('.hero-copy').is_hidden())
            page.locator('#clean').click()
            page.locator('#canvas').focus();page.keyboard.press('h');check(item['id']+' canvas H restores clean-view control',page.locator('.hero-copy').is_hidden());page.keyboard.press('h')
            before=inspect()['playing'];page.keyboard.press('Space');check(item['id']+' canvas SPACE toggles once',inspect()['playing'] is not before)
            check(item['id']+' header has eight peer links',page.locator('.hall-modes > a').count()==8 and page.locator('.hall-modes [aria-current]').count()==1)
            check(item['id']+' header is one visible row',page.locator('.hall-modes').evaluate('(e)=>{const r=[...e.children].map(a=>a.getBoundingClientRect());return e.scrollWidth<=e.clientWidth+1&&r.every(a=>Math.abs(a.top-r[0].top)<1)}'))
            before=inspect()['playing'];page.locator('#about-open').click();check(item['id']+' notes pause playback',inspect()['playing'] is False)
            page.keyboard.press('Escape');page.wait_for_function('(playing)=>!document.querySelector("#about").open&&VisualStudy.inspect().playing===playing',arg=before)
            check(item['id']+' notes restore playback',inspect()['playing'] is before)
            pause();h0=digest();page.wait_for_timeout(130);check(item['id']+' pause is stable',digest()==h0)
            if item['id']=='portal':
                change('穿越进度',100);check('camera crosses portal plane',inspect()['z']<0)
                page.get_by_role('button',name='回头看',exact=True).click();page.wait_for_timeout(70);check('turn back uses camera yaw',inspect()['yaw']>3)
            elif item['id']=='temporal':
                page.get_by_label('运动源',exact=True).select_option('video')
                page.evaluate('VisualStudy.play()');page.wait_for_timeout(3200);pause();state=inspect()
                if not args.inline or args.video_fixture:
                    check('bounded frame cache',1<state['count']<=state['capacity']==64)
                    check('real video decoding',state['source']=='video' and state['readyState']>=2)
                    before=digest();change('历史深度（秒）',0);check('2D time field changes sampled pixels',digest()!=before)
                else:check('missing offline video falls back to chapter art',state['source']=='art' and '读取失败' in page.locator('#status').inner_text())
                page.get_by_label('运动源',exact=True).select_option('synthetic');page.evaluate('VisualStudy.play()');page.wait_for_timeout(180);pause();check('explicit synthetic source works',inspect()['source']=='synthetic')
            elif item['id']=='fluid':
                page.get_by_role('button',name='轻推颜料',exact=True).click();page.evaluate('VisualStudy.play()');page.wait_for_timeout(1200);pause();check('pigment is transported',digest()!=h0)
                check('fluid finite after interaction',inspect()['finite'])
                h1=digest();page.evaluate('VisualStudy.play()');page.wait_for_timeout(300);pause();check('flow continues without pointer',digest()!=h1)
            elif item['id']=='optical':
                change('折射率',1.68);check('refraction parameter changes pixels',digest()!=h0)
                box=page.locator('#canvas').bounding_box();page.mouse.move(box['x']+box['width']*.5,box['y']+box['height']*.5);page.mouse.down();page.mouse.move(box['x']+box['width']*.66,box['y']+box['height']*.45,steps=8);page.mouse.up();page.wait_for_timeout(80);check('lens follows drag',inspect()['pos'][0]>.6)
            elif item['id']=='shadow':
                count=inspect()['voxels'];page.get_by_role('button',name='对齐菱影 · 90°',exact=True).click();page.wait_for_timeout(90);check('projection changes with same geometry',digest()!=h0 and inspect()['voxels']==count and inspect()['angle']>1.5)
            elif item['id']=='folding':
                change('展开程度',0);check('paper closes flat',inspect()['open']==0)
                change('展开程度',100);check('paper opens while connected',inspect()['open']==1)
            # Exercise every local preset through its visible button, then verify
            # actual module state and canvas pixels, not just selected CSS.
            page.locator('#clean').click()
            if item['id']=='temporal':
                page.get_by_label('运动源',exact=True).select_option('video')
                page.evaluate('VisualStudy.play()');page.wait_for_timeout(3200);pause()
            page_url=page.url
            rendered=[]
            cards=page.locator('.study-strip > button')
            for i in range(cards.count()):
                card=cards.nth(i);scene=card.get_attribute('data-scene')
                card.click();pause();state=inspect()
                check(f'{item["id"]} {scene} stays in page and accents selection',page.url==page_url and card.get_attribute('aria-pressed')=='true' and page.locator('.study-strip [aria-current]').count()==1)
                if item['id']=='portal':
                    check(scene+' camera preset',state['auto'] if scene=='roam' else state['target']==(0 if scene=='threshold' else 1) and state['yaw']==(3.141592653589793 if scene=='return' else 0))
                elif item['id']=='temporal':
                    chapter=item['chapters'][i]
                    check(scene+' art and prose',state['chapter']==scene and state['mode']==chapter['mode'] and state['source']=='art' and state['art']==chapter['image'] and page.locator('h1').inner_text().replace('\n','')==''.join(chapter['headline']))
                elif item['id']=='fluid':
                    chapter=item['chapters'][i]
                    check(scene+' artwork and material journal',state['chapter']==scene and state['finite'] and state['steps']==0 and state['source']=='art' and state['art']==chapter['image'] and page.locator('h1').inner_text().replace('\n','')==''.join(chapter['headline']) and page.locator('.hero-copy > p').inner_text()==chapter['body'])
                elif item['id']=='optical':
                    expected=[(1.46,.018,98),(1.46,.05,98),(1.7,.012,125),(1.18,0,72)][i]
                    check(scene+' optical parameters',(state['ior'],state['dispersion'],state['radius'])==expected)
                elif item['id']=='shadow':check(scene+' light angle',abs(state['angle']-i*3.141592653589793/6)<1e-8)
                elif item['id']=='folding':check(scene+' paper pose',state['open']==[.76,0,.5,1,1][i] and abs(state['orbit']-(65*3.141592653589793/180 if scene=='side' else .36))<1e-8)
                rendered.append(digest())
            check(item['id']+' content presets produce distinct canvases',len(set(rendered))>=3)
            page.locator('#study-next').click();pause()
            check(item['id']+' local next wraps to first content',cards.first.get_attribute('aria-pressed')=='true' and page.url==page_url)
            page.locator('#study-prev').click();pause()
            check(item['id']+' local previous wraps to last content',cards.last.get_attribute('aria-pressed')=='true' and page.url==page_url)
            # Existing controls must update the same selection state.
            if item['id']=='portal':change('穿越进度',37)
            elif item['id']=='temporal':page.get_by_label('运动源',exact=True).select_option('video');page.get_by_label('时间形状',exact=True).select_option('radial');page.wait_for_timeout(100)
            elif item['id']=='fluid':page.get_by_role('button',name='轻推颜料',exact=True).click();page.wait_for_timeout(100)
            elif item['id']=='optical':change('折射率',1.31)
            elif item['id']=='shadow':change('光源方位',43)
            elif item['id']=='folding':change('展开程度',34)
            check(item['id']+' controls synchronize selection',page.locator('.study-strip [aria-current]').count()==(1 if item['id'] in ('temporal','fluid') else 0))
            cards.first.click();pause();page.locator('#clean').click()
            with page.expect_download(timeout=4000) as download:
                page.get_by_role('button',name='保存画面',exact=True).click()
            check(item['id']+' exports PNG',download.value.suggested_filename.endswith('.png'))
            path=args.output/(item['id']+'-desktop.png');page.screenshot(path=str(path),full_page=True);result['screenshots'].append(path.name)
            page.set_viewport_size({'width':390,'height':844});page.wait_for_timeout(100)
            check(item['id']+' mobile layout fits',page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'))
            check(item['id']+' mobile local filmstrip visible by default',page.locator('.hall-scene-footer').is_visible() and page.locator('.hall-atlas').is_hidden() and page.locator('.study-footer').evaluate('(e)=>{const r=e.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight+1}'))
            cards.last.click();pause()
            check(item['id']+' mobile last content scrolls into view',cards.last.evaluate('(e)=>{const a=e.getBoundingClientRect(),b=e.parentElement.getBoundingClientRect();return a.left>=b.left&&a.right<=b.right+1}'))
            page.screenshot(path=str(args.output/(item['id']+'-mobile.png')),full_page=True)
            result['screenshots'].append(item['id']+'-mobile.png')
            check(item['id']+' mobile switch scrolls inside viewport',page.locator('.hall-modes').evaluate('(e)=>{const r=e.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&e.scrollWidth>e.clientWidth&&getComputedStyle(e).overflowX==="auto"}'))
            check(item['id']+' active mobile mode visible',page.locator('.hall-modes').evaluate('(e)=>{const r=e.getBoundingClientRect(),a=e.querySelector("[aria-current]").getBoundingClientRect();return a.left>=r.left&&a.right<=r.right}'))
            page.set_viewport_size({'width':320,'height':568});page.wait_for_timeout(100)
            check(item['id']+' narrow phone fits',page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'))
            page.set_viewport_size({'width':390,'height':844})
            page.emulate_media(reduced_motion='reduce');load();page.wait_for_timeout(70);check(item['id']+' honors reduced motion',inspect()['playing'] is False)
            check(item['id']+' no uncaught exceptions: '+repr(errors),not errors)
            page.close()
        browser.close()
    if server:server.shutdown()
    result['passed']=len(result['checks'])
    result['video_fixture']=bool(args.video_fixture)
    (args.output/'results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('TOTAL',result['passed'])

if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--inline',action='store_true',help='Render wholly offline without navigating a URL')
    parser.add_argument('--chromium',help='Optional browser executable path')
    parser.add_argument('--video-fixture',type=Path,help='Optional local MP4 for the offline decoder test; never committed')
    parser.add_argument('--output',type=Path,default=Path(tempfile.gettempdir())/'ctt-study-review')
    run(parser.parse_args())

