import assert from 'node:assert/strict';
import {clipNear,lensRay,shadowSolid,foldingPanels,rx,add} from '../src/studies/math.mjs';
import {Fluid} from '../src/studies/fluid.mjs';
let tests=0;
const near=(a,b,eps=1e-8)=>a.forEach((v,i)=>assert.ok(Math.abs(v-b[i])<eps,`${a} != ${b}`));
const test=(name,fn)=>{fn();tests++;console.log('PASS',name);};
test('near clipping stays finite in front of camera',()=>{const p=clipNear([[-1,0,-1],[1,0,2],[0,1,2]]);assert.equal(p.length,4);p.forEach(v=>{assert.ok(v[2]>=.08-1e-10);assert.ok(v.every(Number.isFinite));});});
test('unit-index sphere does not move background samples',()=>{for(const [x,y] of [[0,0],[.2,.3],[-.6,.5]]){const p=lensRay(x,y,1);near([p.x,p.y],[x,y]);assert.ok(p.length>0);}});
test('different refractive indices actually bend different rays',()=>{const a=lensRay(.4,.2,1.4),b=lensRay(.4,.2,1.6);assert.ok(Math.abs(a.x-b.x)>.05);assert.ok(a.fresnel>=0&&a.fresnel<=1);assert.equal(lensRay(1.1,0,1.5),null);});
test('one immutable solid projects to both required silhouettes',()=>{const {a,b,n,voxels}=shadowSolid(27),A=new Uint8Array(n*n),B=new Uint8Array(n*n);for(const [x,y,z] of voxels){A[y*n+x]=1;B[y*n+z]=1;}assert.deepEqual(A,a);assert.deepEqual(B,b);assert.ok(voxels.length>100);});
test('all sheet hinges stay attached throughout folding',()=>{for(let i=0;i<=100;i++){const open=i/100,p=foldingPanels(open);near(p.left[1],p.center[0]);near(p.left[2],p.center[3]);near(p.right[0],p.center[1]);near(p.right[3],p.center[2]);near(p.floor[0],p.center[0]);near(p.floor[1],p.center[1]);near(p.popup[0],add(rx([-.65,-1.35,0],-open*Math.PI/2),[0,-1,0]));}});
test('pressure projection reduces velocity divergence',()=>{const f=new Fluid(48,30);f.splat(.45,.52,.2,-.1);const before=f.divergenceEnergy();f.project(40);assert.ok(f.divergenceEnergy()<before*.75,`${before} -> ${f.divergenceEnergy()}`);});
test('fluid remains finite over 240 fixed time steps',()=>{const f=new Fluid(32,20);f.splat(.45,.52,.2,-.1);for(let i=0;i<240;i++)f.step(1/60);assert.ok(f.u.every(Number.isFinite));assert.ok(f.v.every(Number.isFinite));assert.ok(f.divergenceEnergy()<.5);});
console.log(`${tests} tests passed.`);
"""Offline-only browser harness. Does not change the production sources.
Uses isolated IIFEs and in-memory asset data URLs when the test environment
forbids navigation. Static graph checks separately verify native ES-module paths.
"""
from pathlib import Path
import re,json,base64
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
ORDER=['math','core','filmstrip','portal','fluid','temporal','optical','shadow','folding']

def bundle(video_fixture: Path | None = None):
    entries=[]
    image_types={'.svg':'image/svg+xml','.png':'image/png','.webp':'image/webp'}
    assets={p.relative_to(ROOT/'assets').as_posix():'data:'+image_types[p.suffix]+';base64,'+base64.b64encode(p.read_bytes()).decode() for p in (ROOT/'assets/studies').rglob('*') if p.suffix in image_types}
    if video_fixture:
        assets['matrix-battle/03-clash.mp4']='data:video/mp4;base64,'+base64.b64encode(video_fixture.read_bytes()).decode()
    for name in ORDER:
        src=(ROOT/'src/studies'/f'{name}.mjs').read_text(encoding='utf-8')
        exports=re.findall(r'export\s+(?:async\s+)?(?:function|class|const)\s+(\w+)',src)
        src=re.sub(r"import\s*\{([^}]+)\}\s*from\s*'./([^']+)';",lambda m:f'const {{{m[1]}}}=M[{json.dumps(m[2])}];',src)
        if name=='core':
            src=re.sub(r"export const ASSETS = .*?;",'export const ASSETS = null;',src)
            src=re.sub(r"export const asset = .*?;",'export const asset = name => ASSET_DATA[name] || "data:video/mp4;base64,";',src)
        src=re.sub(r'\bexport\s+','',src)
        entries.append(f'M["{name}.mjs"]=(()=>{{\n{src}\nreturn {{{",".join(exports)}}};\n}})();')
    main=(ROOT/'src/studies/main.mjs').read_text(encoding='utf-8')
    main=re.sub(r"import\s*\{([^}]+)\}\s*from\s*'./([^']+)';",lambda m:f'const {{{m[1]}}}=M[{json.dumps(m[2])}];',main)
    main=re.sub(r"import\('./([^']+)'\)",lambda m:f'Promise.resolve(M[{json.dumps(m[1])}])',main)
    shell=(ROOT/'src/hall/main.js').read_text(encoding='utf-8')
    return shell+'\nconst ASSET_DATA='+json.dumps(assets)+';const M={};\n'+'\n'.join(entries)+'\n(async()=>{\n'+main+'\n})();'

def inline_page(slug):
    s=(ROOT/'dist'/f'{slug}.html').read_text(encoding='utf-8')
    s=re.sub(r'<link rel="stylesheet" href="([^"]+)"[^>]*>',lambda m:'<style>'+(ROOT/'dist'/m[1]).resolve().read_text(encoding='utf-8')+'</style>',s)
    s=re.sub(r'<script\b(?![^>]*type="application/json")[^>]*>.*?</script>','',s,flags=re.S)
    def thumbnail(match):
        path=(ROOT/'dist'/match[1]).resolve()
        return 'src="data:image/webp;base64,'+base64.b64encode(path.read_bytes()).decode()+'"'
    s=re.sub(r'src="(../assets/studies/atlas/[^\"]+)"',thumbnail,s)
    return s
import json,time,hashlib,os,sys,shutil
from pathlib import Path
from playwright.sync_api import sync_playwright
SOURCE=Path(__file__).resolve().parents[1]
ROOT=SOURCE/'reports'/'browser';ROOT.mkdir(parents=True,exist_ok=True)
HTML=(SOURCE/'dist'/'index.html').read_text(encoding='utf-8')
checks=[];errors=[]
def check(name,fn):
 try:
  detail=fn();checks.append({'test':name,'passed':True,'detail':detail});print('PASS',name,flush=True)
 except Exception as e:
  checks.append({'test':name,'passed':False,'error':str(e)});print('FAIL',name,str(e),flush=True)
def require(v,msg='Assertion failed'):
 if not v:raise AssertionError(msg)
 return v
with sync_playwright() as p:
 launch={'headless':True}
 executable=os.environ.get('CHROME_BIN') or shutil.which('chromium') or shutil.which('google-chrome')
 if executable:launch['executable_path']=executable
 if sys.platform.startswith('linux'):
  launch.update(args=['--no-sandbox','--ignore-gpu-blocklist','--enable-webgl','--use-gl=angle','--use-angle=gl-egl','--disable-dev-shm-usage'],env={**os.environ,'LIBGL_ALWAYS_SOFTWARE':'1','EGL_PLATFORM':'surfaceless'})
 browser=p.chromium.launch(**launch)
 page=browser.new_page(viewport={'width':1440,'height':900},device_scale_factor=1)
 page.on('pageerror',lambda e:errors.append(str(e)))
 requests=[];page.on('request',lambda r:requests.append(r.url[:80]))
 page.set_content(HTML,wait_until='load');page.wait_for_function('window.WarpArchive',timeout=25000)
 page.evaluate('WarpArchive.pause()');page.wait_for_function('WarpArchive.getState().plansReady===5',timeout=60000)
 state=lambda:page.evaluate('WarpArchive.getState()')
 check('Primary WebGL 2 renderer starts without GL errors',lambda:require(state()['engine']=='WEBGL 2' and state()['glError']==0))
 check('Zero external network requests (local Blob worker allowed)',lambda:require(all(u.startswith(('blob:','data:')) for u in requests),requests))
 check('All five desktop plans have unique target cells',lambda:require(page.evaluate('WarpArchive.getMetrics().every(m=>m.bijection && m.count===12160 && m.uniqueTargets===12160)')))
 check('Every actual-image pair lowers mean weighted colour error vs same-position',lambda:require(page.evaluate('WarpArchive.getMetrics().every(m=>m.meanColorError<m.samePositionError)')))
 check('Every actual-image refinement lowers total objective',lambda:require(page.evaluate('WarpArchive.getMetrics().every(m=>m.finalObjective<=m.initialObjective)')))
 check('Five pairs produce five distinct maps',lambda:require(page.evaluate('new Set(WarpArchive.getMetrics().map(m=>m.hash)).size===5')))
 def endpoints():
  out=[]
  for i in range(5):
   data=page.evaluate('(i)=>{WarpArchive.seek(i);return document.getElementById("visual").toDataURL()}',i)
   require(len(data)>50000);out.append(hashlib.sha256(data.encode()).hexdigest()[:12])
  require(len(set(out))==5);return out
 check('All five endpoints display different, nonblank complete images',endpoints)
 def reverse():
  h=[]
  for t in [.46,.73,.46]:
   h.append(page.evaluate('(t)=>{WarpArchive.seek(t);return document.getElementById("visual").toDataURL()}',t))
  require(h[0]==h[2]);require(h[0]!=h[1]);return 'Exact pixel-identical return to p=.46'
 check('Reverse seeking returns to exactly the same pixels',reverse)
 def pause():
  page.evaluate('WarpArchive.seek(.41)');v=state()['position'];page.wait_for_timeout(250);require(state()['position']==v);return v
 check('Paused transition does not drift',pause)
 def controls():
  hashes={}
  for m in ['color','geometry','position']:
   data=page.evaluate('(m)=>{WarpArchive.configure({mapping:m});WarpArchive.seek(.56);return document.getElementById("visual").toDataURL()}',m)
   hashes[m]=hashlib.sha256(data.encode()).hexdigest()[:16]
  page.evaluate('WarpArchive.configure({mapping:"color"})');require(len(set(hashes.values()))==3);return hashes
 check('A/B modes use visibly different mapping at same progress',controls)
 def held():
